let x=$json;
if(!x.operations_spreadsheet_id){try{x=$('04.06 - Restore Created Spreadsheet Context').item.json}catch(e){}}
return [{json:{...x,skipAccount:!x.operations_spreadsheet_id}}];

const ctx=$('04.09 - Normalize Spreadsheet Init Context').item.json;
if($json && $json.error){
  return [{json:{...ctx,invalidSpreadsheet:true,spreadsheetError:String($json.error),missing:[],requests:[],headerData:[]}}];
}
const productHeaders=['Product ID','Product Name','Category','Subcategory','Price','Currency','Stock Qty','Stock Status','Color','Size','SKU','Product Description','Product Image','Image 2','Image 3','Image 4','Image 5','Product URL','Offer','Discount','Aliases','Active','Product Group ID','Variant ID','Variant Name','Updated At','Resolved Image 1','Resolved Image 2','Resolved Image 3','Resolved Image 4','Resolved Image 5','_Image File ID 1','_Image File ID 2','_Image File ID 3','_Image File ID 4','_Image File ID 5','_Image Hash 1','_Image Hash 2','_Image Hash 3','_Image Hash 4','_Image Hash 5'];
const headers={
  Products:productHeaders,
  FAQ:['FAQ ID','Question','Answer','Category','Active','Updated At'],
  Orders:['Order Number','Created At','Status','Customer Name','Phone','Address','Product','Quantity','Unit Price','Delivery Charge','Grand Total','Payment Method','Notes','Conversation ID'],
  HumanSupportQueue:['Conversation ID','Business ID','Business Name','Platform','Account ID','Customer ID','Customer External ID','Latest Customer Message','Latest Message Time','Conversation URL','Mode','Handoff Reason','Handoff Source','Status','Updated At'],
  HumanSupportLatest:['Conversation ID','Business ID','Business Name','Platform','Account ID','Customer ID','Customer External ID','Latest Customer Message','Latest Message Time','Conversation URL','Mode','Handoff Reason','Handoff Source','Status','Updated At'],
  _System:['Key','Value','Updated At']
};
const existing=new Set(($json.sheets||[]).map(s=>s.properties?.title).filter(Boolean));
const missing=Object.keys(headers).filter(t=>!existing.has(t));
const data=missing.map(t=>({range:`${t}!A1`,majorDimension:'ROWS',values:[headers[t]]}));
if(missing.includes('HumanSupportLatest')) data.push({range:'HumanSupportLatest!A2',majorDimension:'ROWS',values:[['=SORT(FILTER(HumanSupportQueue!A2:O,HumanSupportQueue!A2:A<>""),15,FALSE)']]});
if(missing.includes('_System')) data.push({range:'_System!A2',majorDimension:'ROWS',values:[['schema_version','4.2',new Date().toISOString()],['account_key',ctx.account_key,new Date().toISOString()]]});
return [{json:{...ctx,invalidSpreadsheet:false,missing,requests:missing.map(title=>({addSheet:{properties:{title}}})),headerData:data}}];

const ctx=$json.ctx||{};
const productHeaders=['Product ID','Product Name','Category','Subcategory','Price','Currency','Stock Qty','Stock Status','Color','Size','SKU','Product Description','Product Image','Image 2','Image 3','Image 4','Image 5','Product URL','Offer','Discount','Aliases','Active','Product Group ID','Variant ID','Variant Name','Updated At','Resolved Image 1','Resolved Image 2','Resolved Image 3','Resolved Image 4','Resolved Image 5','_Image File ID 1','_Image File ID 2','_Image File ID 3','_Image File ID 4','_Image File ID 5','_Image Hash 1','_Image Hash 2','_Image Hash 3','_Image Hash 4','_Image Hash 5'];
const faqHeaders=['FAQ ID','Question','Answer','Category','Active','Updated At'];
const orderHeaders=['Order Number','Created At','Status','Customer Name','Phone','Address','Product','Quantity','Unit Price','Delivery Charge','Grand Total','Payment Method','Notes','Conversation ID'];
const products=Array.isArray($json.products)?$json.products:[];
const faqs=Array.isArray($json.faqs)?$json.faqs:[];
const orders=Array.isArray($json.orders)?$json.orders:[];
const prows=products.map(p=>{const m=Array.isArray(p.media)?p.media:[];const imgs=[0,1,2,3,4].map(i=>m[i]||'');return [p.externalProductId||'',p.name||'',p.category||'',p.subcategory||'',p.price??'',p.currency||'BDT',p.stockQty??'',p.stockStatus||'',p.color||'',p.size||'',p.sku||'',p.description||'',...imgs,p.productUrl||'',p.offer||'',p.discount||'',p.aliases||'',p.active!==false,p.productGroupId||'',p.variantId||'',p.variantName||'',p.updatedAt||new Date().toISOString(),...imgs,'','','','','','','','','',''];});
const frows=faqs.map(f=>[f.key||'',f.question||'',f.answer||'',f.category||'',f.active!==false,f.updatedAt||new Date().toISOString()]);
const orows=orders.map(o=>[o.orderNumber||'',o.createdAt||'',o.status||'NEW',o.customerName||'',o.phone||'',o.address||'',o.product||'',o.quantity??'',o.unitPrice??'',o.deliveryCharge??0,o.grandTotal??0,o.paymentMethod||'',o.notes||'',o.conversationId||'']);
return [{json:{...ctx,snapshotData:[{range:'Products!A1',majorDimension:'ROWS',values:[productHeaders,...prows]},{range:'FAQ!A1',majorDimension:'ROWS',values:[faqHeaders,...frows]},{range:'Orders!A1',majorDimension:'ROWS',values:[orderHeaders,...orows]}]}}];

const state=$('04.15 - Inspect Account Database State').item.json;const ctx=state.ctx||{};
const ranges=Array.isArray($json.valueRanges)?$json.valueRanges:[];
const findVals=(name)=>{const r=ranges.find(x=>String(x.range||'').replace(/'/g,'').startsWith(name+'!'));return r?.values||[];};
const objects=(vals)=>{if(!vals.length)return[];const h=vals[0].map(v=>String(v||'').trim());return vals.slice(1).map(r=>Object.fromEntries(h.map((k,i)=>[k,r[i]??''])));};
const num=v=>{if(v===null||v===undefined||v==='')return null;const n=Number(String(v).replace(/[,৳₹$€£\s]/g,''));return Number.isFinite(n)?n:null;};
const bool=(v,d=true)=>v===''||v===null||v===undefined?d:!['false','0','no','off','inactive','disabled'].includes(String(v).trim().toLowerCase());
const cleanUrl=v=>{const s=String(v||'').trim();const m=s.match(/^=IMAGE\(\s*["']([^"']+)["']/i);return m?m[1]:s;};
const val=(r,...keys)=>{for(const k of keys){if(r[k]!==undefined&&r[k]!==null&&String(r[k]).trim()!=='')return r[k];}return '';};
const products=[];
for(const r of objects(findVals('Products'))){const name=String(val(r,'Product Name','Name','Product','Title')).trim();if(!name)continue;const desc=String(val(r,'Product Description','Description','Details')).trim();let category=String(val(r,'Category','Product Category','Type')).trim();if(!category){const s=(name+' '+desc).toLowerCase();if(/শাড়ি|শাড়ি|saree|sari/.test(s))category='Saree';else if(/shirt|t-shirt|dress|পাঞ্জাবি|panjabi/.test(s))category='Clothing';else category='Uncategorized';}const group=String(val(r,'Product Group ID')).trim()||name.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-|-$/g,'').slice(0,80)||'product';const productId=String(val(r,'Product ID','ID')).trim();const variant=String(val(r,'Variant ID')).trim()||productId||group;const media=[1,2,3,4,5].map(i=>cleanUrl(val(r,`Resolved Image ${i}`,i===1?'Product Image':`Image ${i}`))).filter(x=>/^https?:\/\//i.test(x));const price=num(val(r,'Price','Price (৳)','Selling Price'));const stockQty=num(val(r,'Stock Qty','Quantity','Qty'));const stockStatus=String(val(r,'Stock Status','Stock')).trim()||(stockQty===null?'':stockQty>0?'In Stock':'Out of Stock');const color=String(val(r,'Color')).trim(),size=String(val(r,'Size')).trim(),sku=String(val(r,'SKU','Product Code')).trim(),variantName=String(val(r,'Variant Name')).trim()||[color,size].filter(Boolean).join(' / ');const summary=[name,variantName,category,price!==null?`${price} ${String(val(r,'Currency')).trim()||'BDT'}`:'',desc].filter(Boolean).join(' | ').slice(0,1200);const aliases=String(val(r,'Aliases')).trim();const searchText=[name,variantName,group,variant,sku,category,color,size,desc,summary,aliases].filter(Boolean).join(' ').toLowerCase();const contentHash=Buffer.from(JSON.stringify({group,variant,sku,name,price,stockQty,stockStatus,color,size,desc,media,aliases})).toString('base64').slice(0,180);products.push({external_product_id:variant||productId||group,product_group_id:group,variant_id:variant,sku,name,variant_name:variantName,category,subcategory:String(val(r,'Subcategory')).trim(),price,currency:String(val(r,'Currency')).trim()||'BDT',stock_qty:stockQty,stock_status:stockStatus,color,size,description:desc,summary,product_url:String(val(r,'Product URL','URL','Link')).trim(),image_url:media[0]||'',offer:String(val(r,'Offer')).trim(),discount:String(val(r,'Discount')).trim(),aliases,search_text:searchText,content_hash:contentHash,active:bool(val(r,'Active'),true),media});}
const faqs=[];for(const r of objects(findVals('FAQ'))){const answer=String(val(r,'Answer','Response')).trim();if(!answer)continue;const q=String(val(r,'Question','FAQ','Query')).trim();const key=String(val(r,'FAQ ID','ID','Key')).trim()||Buffer.from((q+'|'+answer).toLowerCase()).toString('base64').slice(0,80);const category=String(val(r,'Category')).trim();faqs.push({external_key:key,question:q,answer,category,search_text:[q,answer,category].join(' ').toLowerCase(),content_hash:Buffer.from(JSON.stringify({q,answer,category})).toString('base64').slice(0,180),active:bool(val(r,'Active'),true)});}
const orders=[];let oi=0;for(const r of objects(findVals('Orders'))){oi++;const product=String(val(r,'Product','Product Name')).trim();const phone=String(val(r,'Phone','Mobile')).trim();const customerName=String(val(r,'Customer Name','Name')).trim();let orderNumber=String(val(r,'Order Number','Order ID','ID')).trim();if(!orderNumber)orderNumber=`IMPORT-${ctx.id}-${Buffer.from([phone,customerName,product,oi].join('|')).toString('hex').slice(0,16)}`;const rawDate=String(val(r,'Created At','Date')).trim();const d=rawDate&&Number.isFinite(Date.parse(rawDate))?new Date(rawDate).toISOString():'';orders.push({order_number:orderNumber,created_at:d,status:String(val(r,'Status')).trim()||'NEW',customer_name:customerName,phone,address:String(val(r,'Address')).trim(),product,quantity:num(val(r,'Quantity','Qty'))||1,unit_price:num(val(r,'Unit Price','Price'))||0,delivery_charge:num(val(r,'Delivery Charge'))||0,grand_total:num(val(r,'Grand Total','Total'))||0,payment_method:String(val(r,'Payment Method')).trim(),note:String(val(r,'Notes','Note')).trim(),customer_external_id:phone?`sheet:${phone}`:`sheet-order:${orderNumber}`});}
return [{json:{...ctx,seedProducts:products,seedFaqs:faqs,seedOrders:orders}}];

