WITH ps AS (
 SELECT * FROM jsonb_to_recordset($3::jsonb) AS x(external_product_id text,product_group_id text,variant_id text,sku text,name text,variant_name text,category text,subcategory text,price numeric,currency text,stock_qty int,stock_status text,color text,size text,description text,summary text,product_url text,image_url text,offer text,discount text,aliases text,search_text text,content_hash text,active boolean,media jsonb)
), pu AS (
 INSERT INTO products(business_id,account_id,external_product_id,product_group_id,variant_id,sku,name,variant_name,category,subcategory,price,currency,stock_qty,stock_status,color,size,description,ai_summary,attributes_json,product_url,image_url,offer,discount,aliases,search_text,content_hash,active,updated_at)
 SELECT $1,$2::bigint,external_product_id,product_group_id,variant_id,sku,name,variant_name,category,subcategory,price,COALESCE(NULLIF(currency,''),'BDT'),stock_qty,stock_status,color,size,description,summary,'{}'::jsonb,product_url,image_url,offer,discount,aliases,search_text,content_hash,COALESCE(active,TRUE),NOW() FROM ps
 ON CONFLICT(account_id,external_product_id) DO UPDATE SET product_group_id=EXCLUDED.product_group_id,variant_id=EXCLUDED.variant_id,sku=EXCLUDED.sku,name=EXCLUDED.name,variant_name=EXCLUDED.variant_name,category=EXCLUDED.category,subcategory=EXCLUDED.subcategory,price=EXCLUDED.price,currency=EXCLUDED.currency,stock_qty=EXCLUDED.stock_qty,stock_status=EXCLUDED.stock_status,color=EXCLUDED.color,size=EXCLUDED.size,description=EXCLUDED.description,ai_summary=EXCLUDED.ai_summary,product_url=EXCLUDED.product_url,image_url=EXCLUDED.image_url,offer=EXCLUDED.offer,discount=EXCLUDED.discount,aliases=EXCLUDED.aliases,search_text=EXCLUDED.search_text,content_hash=EXCLUDED.content_hash,active=EXCLUDED.active,updated_at=NOW() RETURNING id
), md AS (
 DELETE FROM product_media pm USING products p WHERE pm.product_id=p.id AND p.account_id=$2::bigint RETURNING pm.id
), mi AS (
 INSERT INTO product_media(product_id,media_key,source_type,source_ref,resolved_url,sort_order,active,updated_at)
 SELECT p.id,'image-'||m.ord::text,'url',m.url,m.url,m.ord::int,TRUE,NOW() FROM ps s JOIN products p ON p.account_id=$2::bigint AND p.external_product_id=s.external_product_id CROSS JOIN LATERAL jsonb_array_elements_text(COALESCE(s.media,'[]'::jsonb)) WITH ORDINALITY m(url,ord)
 ON CONFLICT(product_id,media_key) DO UPDATE SET source_ref=EXCLUDED.source_ref,resolved_url=EXCLUDED.resolved_url,sort_order=EXCLUDED.sort_order,active=TRUE,updated_at=NOW() RETURNING product_id
) SELECT 1;
WITH fs AS (SELECT * FROM jsonb_to_recordset($4::jsonb) AS x(external_key text,question text,answer text,category text,search_text text,content_hash text,active boolean))
INSERT INTO knowledge_base(business_id,account_id,external_key,question,answer,category,search_text,content_hash,active,updated_at)
SELECT $1,$2::bigint,external_key,question,answer,category,search_text,content_hash,COALESCE(active,TRUE),NOW() FROM fs
ON CONFLICT(account_id,external_key) DO UPDATE SET question=EXCLUDED.question,answer=EXCLUDED.answer,category=EXCLUDED.category,search_text=EXCLUDED.search_text,content_hash=EXCLUDED.content_hash,active=EXCLUDED.active,updated_at=NOW();
WITH os AS (SELECT * FROM jsonb_to_recordset($5::jsonb) AS x(order_number text,created_at text,status text,customer_name text,phone text,address text,product text,quantity int,unit_price numeric,delivery_charge numeric,grand_total numeric,payment_method text,note text,customer_external_id text)), cs AS (
 SELECT DISTINCT ON (customer_external_id) customer_external_id,customer_name,phone FROM os WHERE COALESCE(customer_external_id,'')<>'' ORDER BY customer_external_id
)
INSERT INTO customers(business_id,account_id,platform,external_user_id,name,phone,updated_at)
SELECT $1,$2::bigint,(SELECT platform FROM business_accounts WHERE id=$2::bigint),customer_external_id,customer_name,phone,NOW() FROM cs
ON CONFLICT(account_id,external_user_id) DO UPDATE SET name=COALESCE(NULLIF(EXCLUDED.name,''),customers.name),phone=COALESCE(NULLIF(EXCLUDED.phone,''),customers.phone),updated_at=NOW();
WITH os AS (SELECT * FROM jsonb_to_recordset($5::jsonb) AS x(order_number text,created_at text,status text,customer_name text,phone text,address text,product text,quantity int,unit_price numeric,delivery_charge numeric,grand_total numeric,payment_method text,note text,customer_external_id text))
INSERT INTO orders(order_number,customer_id,business_id,account_id,status,customer_name,phone,address,payment_method,note,subtotal,delivery_charge,total,created_at,updated_at)
SELECT o.order_number,c.id,$1,$2::bigint,COALESCE(NULLIF(o.status,''),'NEW'),o.customer_name,o.phone,o.address,o.payment_method,o.note,GREATEST(COALESCE(o.grand_total,0)-COALESCE(o.delivery_charge,0),0),COALESCE(o.delivery_charge,0),COALESCE(o.grand_total,0),COALESCE(NULLIF(o.created_at,'')::timestamptz,NOW()),NOW()
FROM os o JOIN customers c ON c.account_id=$2::bigint AND c.external_user_id=o.customer_external_id
ON CONFLICT(order_number) DO UPDATE SET status=EXCLUDED.status,customer_name=EXCLUDED.customer_name,phone=EXCLUDED.phone,address=EXCLUDED.address,payment_method=EXCLUDED.payment_method,note=EXCLUDED.note,subtotal=EXCLUDED.subtotal,delivery_charge=EXCLUDED.delivery_charge,total=EXCLUDED.total,updated_at=NOW();
WITH os AS (SELECT * FROM jsonb_to_recordset($5::jsonb) AS x(order_number text,created_at text,status text,customer_name text,phone text,address text,product text,quantity int,unit_price numeric,delivery_charge numeric,grand_total numeric,payment_method text,note text,customer_external_id text)), gone AS (
 DELETE FROM order_items oi USING orders o,os s WHERE oi.order_id=o.id AND o.order_number=s.order_number RETURNING oi.id
)
INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price,total)
SELECT o.id,(SELECT p.id FROM products p WHERE p.account_id=$2::bigint AND lower(p.name)=lower(s.product) ORDER BY p.id LIMIT 1),COALESCE(NULLIF(s.product,''),'Imported item'),GREATEST(COALESCE(s.quantity,1),1),COALESCE(s.unit_price,0),GREATEST(COALESCE(s.quantity,1),1)*COALESCE(s.unit_price,0)
FROM os s JOIN orders o ON o.order_number=s.order_number WHERE COALESCE(s.product,'')<>'';
SELECT $6::jsonb AS ctx;

INSERT INTO system_settings(key,value,updated_at)
VALUES('ops_sheet_bound:'||$1::text,$2,NOW())
ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=NOW();
SELECT $3::jsonb AS ctx;
